mapper.insert:
INSERT INTO ai_task (
    task_id, task_type, status, priority, input_json, options_json,
    provider, model, attempt_count, max_attempts, input_tokens,
    output_tokens, created_at, updated_at
) VALUES (
    #{taskId}, #{taskType}, #{status}, #{priority}, #{inputJson}, #{optionsJson},
    #{provider}, #{model}, #{attemptCount}, #{maxAttempts}, #{inputTokens},
    #{outputTokens}, #{createdAt}, #{updatedAt}
)

mapper.select:
SELECT 
FROM ai_task
WHERE status = 'RUNNING'
  AND lease_owner = #{runnerId}
  AND lease_token = #{claimToken}
ORDER BY id ASC

