INSERT INTO ai_task_attempt (
    ai_task_id, attempt_no, lease_token, provider, model, status,
    retryable, error_type, error_code, error_message, input_tokens,
    output_tokens, started_at, finished_at, duration_ms
) VALUES (
    #{aiTaskId}, #{attemptNo}, #{leaseToken}, #{provider}, #{model}, #{status},
    #{retryable}, #{errorType}, #{errorCode}, #{errorMessage}, #{inputTokens},
    #{outputTokens}, #{startedAt}, #{finishedAt}, #{durationMs}
)
